//! Copies the cache policy generated by Nix into `OUT_DIR`.
//!
//! The four numbers live in `assets/cache.nix` and `nix/cache.nix` turns them
//! into Rust. This does NOT generate them — generating here would leave the one
//! source of truth and reimplement Nix logic (invariant 5). It is the shape
//! `ronoctua-brain`'s own build script already has, down to the reason the
//! destination is deleted first.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_CACHE_RS");

    let generated = env::var("RONOCTUA_CACHE_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_CACHE_RS is not set.\n\
             \n\
             The cache policy is generated by Nix out of assets/cache.nix.\n\
             Enter the environment with `direnv allow` (or `nix develop`), which\n\
             sets the variable, or build through the flake with `nix build`."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("cache.rs");
    // DELETE FIRST: the file comes from the store read-only, and `fs::copy`
    // inherits the mode along with the content — the second build fails with
    // "Permission denied" inside a build script.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
